using BCLMSApi.Data; using BCLMSApi.Services; using Microsoft.AspNetCore.Mvc;
namespace BCLMSApi.Controllers;
[ApiController][Route("api/invoices")]
public class InvoicesController(Datalayer datalayer, IUserTokenService tokens) : ControllerBase
{
 [HttpPost] public async Task<ActionResult> Save(InvoiceRequest r) { var u=tokens.GetValidTokenPayload(Request.Headers.Authorization); if(u is null)return Unauthorized(); await using var c=datalayer.CreateTextCommand("IF NOT EXISTS(SELECT 1 FROM dbo.ApplicationInvoices WHERE ApplicationId=@A) BEGIN INSERT dbo.ApplicationInvoices(ApplicationId,PaymentReference,GlAccountNumber) VALUES(@A,@R,@G); DECLARE @I INT=SCOPE_IDENTITY(); INSERT dbo.ApplicationInvoiceLines(ApplicationInvoiceId,ItemCode,Description,Amount) SELECT @I,ItemCode,Description,Amount FROM OPENJSON(@L) WITH(ItemCode nvarchar(50),Description nvarchar(250),Amount decimal(18,2)); END"); c.Parameters.AddWithValue("@A",r.ApplicationId);c.Parameters.AddWithValue("@R",r.PaymentReference);c.Parameters.AddWithValue("@G",r.GlAccountNumber);c.Parameters.AddWithValue("@L",System.Text.Json.JsonSerializer.Serialize(r.Lines));await c.Connection!.OpenAsync();await c.ExecuteNonQueryAsync();return Ok(); }
 [HttpGet("{applicationId:int}")] public async Task<ActionResult> Get(int applicationId){var u=tokens.GetValidTokenPayload(Request.Headers.Authorization);if(u is null)return Unauthorized();await using var c=datalayer.CreateTextCommand("SELECT i.PaymentReference,i.GlAccountNumber,i.PaymentStatus,l.ItemCode,l.Description,l.Amount FROM dbo.ApplicationInvoices i JOIN dbo.ApplicationInvoiceLines l ON l.ApplicationInvoiceId=i.ApplicationInvoiceId WHERE i.ApplicationId=@A");c.Parameters.AddWithValue("@A",applicationId);await c.Connection!.OpenAsync();await using var r=await c.ExecuteReaderAsync();var lines=new List<object>();string? reference=null,gl=null,status=null;while(await r.ReadAsync()){reference??=r.GetString(0);gl??=r.GetString(1);status??=r.GetString(2);lines.Add(new{itemCode=r.GetString(3),description=r.GetString(4),amount=r.GetDecimal(5)});}if(reference is null)return Ok(new{paymentReference="",glAccountNumber="",paymentStatus="Unavailable",lines});return Ok(new{paymentReference=reference,glAccountNumber=gl,paymentStatus=status,lines});}
 [HttpGet("{applicationId:int}/transactions")] public async Task<ActionResult> Transactions(int applicationId){var u=tokens.GetValidTokenPayload(Request.Headers.Authorization);if(u is null)return Unauthorized();await using var c=datalayer.CreateTextCommand("IF OBJECT_ID('dbo.ApplicationPaymentTransactions','U') IS NOT NULL SELECT PaymentReference,Amount,PaymentMonth,PaymentStatus,RecordedDate FROM dbo.ApplicationPaymentTransactions WHERE ApplicationId=@A ORDER BY PaymentMonth DESC; ");c.Parameters.AddWithValue("@A",applicationId);await c.Connection!.OpenAsync();await using var r=await c.ExecuteReaderAsync();var transactions=new List<object>();while(await r.ReadAsync())transactions.Add(new{paymentReference=r.GetString(0),amount=r.GetDecimal(1),paymentMonth=r.GetDateTime(2),paymentStatus=r.GetString(3),recordedDate=r.GetDateTime(4)});return Ok(transactions);}
 [HttpPost("{applicationId:int}/confirm-payment")] public async Task<ActionResult> Confirm(int applicationId){var u=tokens.GetValidTokenPayload(Request.Headers.Authorization);if(u is null||u.IsCustomer)return Forbid();await using var c=datalayer.CreateTextCommand("DECLARE @Amount DECIMAL(18,2)=(SELECT SUM(Amount) FROM dbo.ApplicationInvoiceLines l JOIN dbo.ApplicationInvoices i ON i.ApplicationInvoiceId=l.ApplicationInvoiceId WHERE i.ApplicationId=@A); DECLARE @Reference NVARCHAR(100)=(SELECT PaymentReference FROM dbo.ApplicationInvoices WHERE ApplicationId=@A); UPDATE dbo.ApplicationInvoices SET PaymentStatus='Confirmed',ConfirmedDate=SYSUTCDATETIME(),ConfirmedByUserId=@U WHERE ApplicationId=@A AND PaymentStatus<>'Confirmed'; IF @@ROWCOUNT>0 AND OBJECT_ID('dbo.ApplicationPaymentTransactions','U') IS NOT NULL INSERT dbo.ApplicationPaymentTransactions(ApplicationId,PaymentReference,Amount,PaymentMonth,RecordedByUserId) SELECT @A,@Reference,@Amount,DATEFROMPARTS(YEAR(GETUTCDATE()),MONTH(GETUTCDATE()),1),@U WHERE NOT EXISTS(SELECT 1 FROM dbo.ApplicationPaymentTransactions WHERE ApplicationId=@A AND PaymentMonth=DATEFROMPARTS(YEAR(GETUTCDATE()),MONTH(GETUTCDATE()),1));");c.Parameters.AddWithValue("@A",applicationId);c.Parameters.AddWithValue("@U",u.UserId);await c.Connection!.OpenAsync();return await c.ExecuteNonQueryAsync()>0?Ok():NotFound();}
}
public class InvoiceRequest{public int ApplicationId{get;set;} public string PaymentReference{get;set;}="";public string GlAccountNumber{get;set;}="";public List<InvoiceLineRequest> Lines{get;set;}=[];} public class InvoiceLineRequest{public string ItemCode{get;set;}="";public string Description{get;set;}="";public decimal Amount{get;set;}}
